commands.windows:
# Standalone example: domain membership and the signed-in user's AD groups, as text.
$cs = Get-CimInstance Win32_ComputerSystem
"domain: " + $(if ($cs.PartOfDomain) { $cs.Domain } else { 'none (workgroup)' })
if ($cs.PartOfDomain -and $cs.UserName) {
  $n = ($cs.UserName -split '\\')[-1]
  $r = ([adsisearcher]"(&(objectCategory=person)(sAMAccountName=$n))").FindOne()
  if ($r) { $r.Properties['memberof'] | ForEach-Object { "$n: " + (($_ -split ',')[0] -replace '^CN=') } }
}
